<script setup lang="ts">
import { stringify } from 'yaml'
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { getHyperparameterTemplate, type HyperparameterTemplate } from '../api/hyperparameters'
const route=useRoute();const item=ref<HyperparameterTemplate>();const error=ref('');const raw=computed(()=>item.value?stringify(item.value.effective_parameters,{lineWidth:0}):'');onMounted(async()=>{try{item.value=await getHyperparameterTemplate(String(route.params.id))}catch(reason){error.value=reason instanceof Error?reason.message:'模板详情加载失败'}})
</script>
<template><main class="content-page detail-page"><header class="content-toolbar"><div class="content-toolbar-title"><h1>{{ item?.name||'模板详情' }}</h1><el-tag v-if="item?.system_key" effect="plain">系统模板</el-tag></div><router-link v-if="item" :to="`/hyperparameter-templates/new?from=${item.id}`"><el-button type="primary">派生模板</el-button></router-link></header><div class="content-body"><el-alert v-if="error" :title="error" type="error" :closable="false"/><section v-if="item" class="detail-grid"><div><span>epochs</span><strong>{{ item.epochs }}</strong></div><div><span>batch size</span><strong>{{ item.batch_mode==='auto'?'auto':item.batch_value }}</strong></div><div><span>image size</span><strong>{{ item.image_size }}</strong></div><div><span>目录版本</span><code>{{ item.catalog_version }}</code></div><article><span>描述</span><p>{{ item.description||'暂无描述' }}</p></article><article><span>RAW 配置</span><pre>{{ raw }}</pre></article></section></div></main></template>
<style scoped>.detail-page{background:#f4f7fa}.detail-grid{margin-top:24px;display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:#d8dee6;border:1px solid #d8dee6}.detail-grid>*{padding:20px;background:#fff}.detail-grid span{display:block;margin-bottom:7px;color:#687482;font-size:12px}.detail-grid article{grid-column:1/-1}.detail-grid p{margin:0}.detail-grid pre{margin:0;padding:18px;background:#111827;color:#dbeafe;overflow:auto}@media(max-width:800px){.detail-grid{grid-template-columns:1fr 1fr}}</style>
